import pytest


def shout(xs: list[str]) -> None:
    """Print each string in xs upper-cased on its own line."""
    for s in xs:
        print(s.upper())


def test_shout_basic(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["hello", "world"])
    assert capsys.readouterr().out == "HELLO\nWORLD\n"


def test_shout_empty_list(capsys: pytest.CaptureFixture[str]) -> None:
    shout([])
    assert capsys.readouterr().out == ""


def test_shout_mixed_case_and_symbols(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["MiXeD", "abc123", "!?"])
    assert capsys.readouterr().out == "MIXED\nABC123\n!?\n"


def test_shout_empty_string(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["", "a"])
    assert capsys.readouterr().out == "\nA\n"


def test_shout_returns_none_and_keeps_input(capsys: pytest.CaptureFixture[str]) -> None:
    xs = ["a", "b"]
    assert shout(xs) is None  # type: ignore[func-returns-value]
    assert xs == ["a", "b"]
    assert capsys.readouterr().out == "A\nB\n"
